import os,sys,json,base64,zlib,subprocess,hashlib
from pathlib import Path
code=Path('/kaggle/working/code');code.mkdir(exist_ok=True)
for name,value in json.loads(zlib.decompress(base64.b64decode(''))).items():
 p=code/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(value)
os.environ['PYTHONPATH']=str(code/'src')+os.pathsep+str(code)
subprocess.run([sys.executable,'-m','pip','install','pytest'],check=True)
out=Path('/kaggle/working/out');out.mkdir(exist_ok=True)
result=subprocess.run([sys.executable,'-m','pytest','-q',str(code/'tests')],cwd=code,capture_output=True,text=True)
(out/'pytest.txt').write_text(result.stdout+result.stderr)
(out/'config.json').write_text(json.dumps(dict(source='a9d5580',seed=20261014,scope='six pending synthetic test modules, not full repository suite',returncode=result.returncode,runner_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()),indent=2))
